protected void loopRecords()
{
    QueryRun queryRun = new QueryRun(query);

    METProcMetrics procMetrics = METProcMetricsScope::current();
    if (procMetrics)
    {
        procMetrics.setTotalCountFromQuery(queryRun);
        procMetrics.setDescription(2, 'Process Started');
        procMetrics.beginTrace();
    }
    next loopRecords();

}
